import sys
def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    xs = list(map(int, data[1:1 + int(data[0])]))
    for i in range(len(xs)):
        for j in range(i + 1, len(xs)):
            if xs[j] < xs[i]:
                xs[i], xs[j] = xs[j], xs[i]
    print(' '.join(map(str, xs)))
main()

