import sys
def main():
    data = sys.stdin.read().strip().split()
    if len(data) < 3:
        print('-1 -1')
        return
    n, t = int(data[0]), int(data[1])
    xs = list(map(int, data[2:2 + n]))
    for i in range(len(xs)):
        for j in range(i + 1, len(xs)):
            if xs[i] + xs[j] == t:
                print(f'{i} {j}')
                return
    print('-1 -1')
main()

