import sys
def main():
    data = sys.stdin.read().strip().split()
    if len(data) < 3:
        print('-1 -1')
        return
    n, t = int(data[0]), int(data[1])
    xs = list(map(int, data[2:2 + n]))
    seen = {}
    for i, x in enumerate(xs):
        if t - x in seen:
            print(f'{seen[t - x]} {i}')
            return
        seen[x] = i
    print('-1 -1')
main()

