import sys
def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    xs = list(map(int, data[1:1 + int(data[0])]))
    best, bestc = None, -1
    for x in xs:
        c = sum(1 for y in xs if y == x)
        if c > bestc or (c == bestc and (best is None or x < best)):
            best, bestc = x, c
    print(best if best is not None else '')
main()

