#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n; if (!(cin >> n)) return 0;
    vector<long long> xs(n);
    for (int i = 0; i < n; i++) cin >> xs[i];
    for (int i = 0; i < n; i++) for (int j = i + 1; j < n; j++)
        if (xs[j] < xs[i]) swap(xs[i], xs[j]);
    for (int i = 0; i < n; i++) { if (i) cout << ' '; cout << xs[i]; }
    if (n) cout << '\n';
    return 0;
}

