const d = fs.readFileSync(0, 'utf8').trim().split(/\s+/).filter(Boolean);
let n = d.length ? BigInt(d[0]) : 0n;
console.log((n * (n + 1n) * (2n * n + 1n) / 6n).toString());

original_code:
const fs = require('fs');
const d = fs.readFileSync(0, 'utf8').trim().split(/\s+/).filter(Boolean);
if (!d.length) process.exit(0);
const toks = d.slice(1, 1 + Number(d[0]));
let s = '';
for (const t of toks) s += t + '\n';
process.stdout.write(s);

